#include <stdint.h>
#define STM32G474xx
#include "stm32g4xx.h"
#include "adc.h"
#include "kobuki.h"
#include "uart.h"
#include "ultrasonic.h"
#include "SearchFSM.h"
#include "OrientFSM.h"
#include "PathFindFSM.h"
#include "StorageFSM.h"
#include "DepositFSM.h"

/* Kobuki button values */
# define BUTTON_0_START 0x01U
# define BUTTON_1_STOP 0x02U
# define BUTTON_2_ROTATE 0x04U

// Logic
# define FALSE 0
# define TRUE 1
// States

static enum {
    IDLE, 
    SEARCH,
    ORIENT,
    PATHFIND,
    STORAGE,
    DEPOSIT
} state ;

typedef enum {
    SCAN, 
    OBJDETECT,
    OBJINVESTIGATE, 
    BOLLARDFOUND 
} SearchFSM_State;

int main(void) {
    // Both of these only for testing purposes . Not required
    volatile uint16_t ultrasonic_read;
    volatile uint16_t adc_read;
    Kobuki_Typedef kobuki ;
    US_Typedef object ;
    Kobuki_LED_Enum led_1 , led_2 ;

    UART_Init();
    ADC_Init();
    Ultrasonic_Init();
    state = IDLE;
    led_1 = OFF;
    led_2 = OFF;

    while (1){
        Kobuki_Read(&kobuki);
        Ultrasonic_Detect(&object);
        // Both of these only for testing purposes . Not required
        ultrasonic_read = Ultrasonic_Read ();
        adc_read = ADC_Read ( ADC_CHANNEL_1 );
        Kobuki_Update_LEDs (led_1 , led_2 );

        // A TEST FSM
        switch(state){
            case IDLE:
                if(kobuki.button == BUTTON_0_START){
                    state = SEARCH;
                    led_1 = RED;
                    Kobuki_Rotate_Angle_Setpoint(kobuki .angle,450);
                    // Kobuki_Drive_Distance_Setpoint ( kobuki.distance ,100) ;
                } else if ( kobuki.button == BUTTON_1_STOP ){
                    state = SEARCH ;
                    led_1 = RED;
                    Kobuki_Rotate_Angle_Setpoint ( kobuki .angle, 270) ;
                    // Kobuki_Drive_Distance_Setpoint ( kobuki.distance , -100) ;
                } else if (kobuki.button == BUTTON_2_ROTATE){
                    state = SEARCH ;
                    led_1 = RED;
                    Kobuki_Rotate_Angle_Setpoint ( kobuki .angle , 90);
                    // Kobuki_Drive_Distance_Setpoint ( kobuki . distance ,1000) ;
                } else {
                    Kobuki_Drive(STOP);
                }
                break;

            case SEARCH:
                // Parent only handles emergencies. Cliff and bumper are handled in search FSM
                if ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP)){
                    state = IDLE;
                    led_1 = YELLOW;
                    Kobuki_Drive(STOP);
                } 
                // Run SearchFSM each loop. Once it returns SEARCH_DONE, transition to ORIENT state
                else if(SearchFSM_Run(&kobuki, &object) == SEARCH_DONE){
                    state = ORIENT;
                    led_1 = GREEN;
                    Kobuki_Drive(STOP);
                }
                break;

            case ORIENT:
                if ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP)){
                    state = IDLE;
                    led_1 = YELLOW;
                    Kobuki_Drive(STOP);
                }
                break;
            
            case PATHFIND:
                if ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP)){
                    state = IDLE;
                    led_1 = YELLOW;
                    Kobuki_Drive(STOP);
                }
                break;  

            case STORAGE:
                if ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP)){
                    state = IDLE;
                    led_1 = YELLOW;
                    Kobuki_Drive(STOP);
                }
                break;  

            case DEPOSIT:
                if ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP)){
                    state = IDLE;
                    led_1 = YELLOW;
                    Kobuki_Drive(STOP);
                }
                break;  

        }
    }
}
